+/** Chooses a supported language from an `Accept-Language` header, or `fallback`. */
+export function pickLanguage(header, fallback = "en") {
+  if (typeof header !== "string" || !header.trim()) return fallback;
+  let bestLang = null;
+  let bestQ = 0;
+  for (const part of header.split(",")) {
+    const trimmed = part.trim();
+    if (!trimmed) continue;
+    const segments = trimmed.split(";");
+    if (segments.length > 2) continue;
+    const tag = segments[0].trim();
+    if (!/^[a-z]{1,8}(?:-[a-z0-9]{1,8})*$/i.test(tag)) continue;
+    let q = 1;
+    if (segments.length === 2) {
+      const param = segments[1].trim();
+      const eq = param.indexOf("=");
+      if (eq === -1 || param.slice(0, eq).trim().toLowerCase() !== "q") continue;
+      const qStr = param.slice(eq + 1).trim();
+      if (!/^(?:0(?:\.\d{0,3})?|1(?:\.0{0,3})?)$/.test(qStr)) continue;
+      q = Number(qStr);
+    }
+    if (q <= 0) continue;
+    const primary = tag.split("-")[0].toLowerCase();
+    if (!LANGUAGES.includes(primary)) continue;
+    if (q > bestQ) {
+      bestQ = q;
+      bestLang = primary;
+    }
+  }
+  return bestLang ?? fallback;
+}
